const item = $input.first();
const files = item.json.files ?? [];
const binary = item.binary ?? {};

const lines = files.map((f, i) => {
  const b = binary[f.binaryKey] ?? {};
  return `${i + 1}. **${f.fileName}** | type: ${f.mimeType} | size: ${f.fileSize} | binary key: \`${f.binaryKey}\` | stored as: ${b.id ? 'filesystem' : 'inline'}`;
});

const output = [
  `**Question:** ${item.json.chatInput || '(none)'}`,
  `**Session:** ${item.json.sessionId}`,
  files.length ? `**Files received:**\n${lines.join('\n')}` : 'No files attached.',
].join('\n\n');

return [{ json: { output } }];
